/* `node --test scripts/`: the generated troubleshooting table, and what happens when CONTRIBUTING.md lacks its markers. */
import './lib/test-env.mjs';
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { FAILURES } from './lib/recovery.mjs';
import { renderTable, withTable } from './troubleshooting.mjs';

const START =
  '<!-- troubleshooting:start (generated by node scripts/troubleshooting.mjs from scripts/lib/recovery.mjs) -->';
const END = '<!-- troubleshooting:end -->';

test('one row per failure, in the order recovery.mjs tries them', () => {
  const rows = renderTable().split('\n').slice(2);
  assert.equal(rows.length, FAILURES.length);
  assert.deepEqual(
    rows.map((row) => row.match(/^\| `([^`]+)`/)[1]),
    FAILURES.map(({ kind }) => kind),
  );
});

test('cells escape pipes and placeholders, and wrap addresses so they are no bare links', () => {
  const table = renderTable([
    { kind: 'x', why: 'a | b', fix: 'pnpm --filter <package>\n  then ssh -T git@github.com' },
  ]);
  const row = table.split('\n')[2];
  assert.equal(row, '| `x` | a \\| b | — | pnpm --filter &lt;package&gt; then ssh -T `git@github.com` |');
});

test('a CONTRIBUTING.md without the markers is an error, not a silent no-op', () => {
  assert.throws(() => withTable('# Contributing\n', 'T'), /troubleshooting:start/);
  assert.throws(() => withTable(`${END}\n${START}\n`, 'T'), /troubleshooting:start/);
});

test('the block between the markers is replaced, the rest kept, and a second run changes nothing', () => {
  const before = `intro\n${START}\nold table\n${END}\noutro\n`;
  const once = withTable(before, 'T');
  assert.ok(once.startsWith(`intro\n${START}\n\n`));
  assert.ok(once.endsWith(`${END}\noutro\n`));
  assert.ok(once.includes('<!-- prettier-ignore-start -->\nT\n<!-- prettier-ignore-end -->'));
  assert.doesNotMatch(once, /old table/);
  assert.equal(withTable(once, 'T'), once);
});
